/**
 * Managed Postgres and Redis. Each is one container built by containerSpec(): its named data
 * volume, its environment's private network, a DNS alias equal to the app name, and no published
 * port, ever. Other apps in the environment reach it by name; nothing on the host or the internet
 * can. A service never gets the project's variables: everything it runs with is set here.
 *
 * Credentials are generated by the api and stored sealed as one JSON value (App.passwordSecretId,
 * @dockify/db service-credentials), so a service never runs with a default or empty password. The
 * password never goes on argv or into the container's environment: the managed deploy writes it
 * into the service's own volume (Redis reads its whole config from there, Postgres reads
 * POSTGRES_PASSWORD_FILE), see data/managed.ts. Only the throwaway restore-test Postgres, on an
 * internal network with a password nothing else ever uses, still takes POSTGRES_PASSWORD.
 *
 * Storage (MinIO) is not offered: minio/minio is no longer published as an image, and the project
 * was archived upstream. The kind stays in the schema for rows older installs created; every path
 * that would run one refuses with STORAGE_UNAVAILABLE.
 */
import { setTimeout as sleep } from "node:timers/promises";
import { RESERVED_NAME_PREFIX } from "@dockify/contracts";
import {
  generateServiceCredentials, parseServiceCredentials, type ServiceCredentials, type ServiceKindName,
} from "@dockify/db";
import { assertSafeSpec, containerSpec, type ContainerInput, type ContainerSpec } from "@dockify/engine";
import type { DockerPort } from "./docker-port.ts";

export type ServiceKind = ServiceKindName;
export type { ServiceCredentials } from "@dockify/db";

export const STORAGE_UNAVAILABLE =
  "Storage services are not available: MinIO no longer publishes an image Dockify can run. Add S3 compatible storage from your provider in Settings, Integrations instead.";

export class ProvisionError extends Error {
  readonly permanent: boolean;
  constructor(message: string, permanent = false) {
    super(message);
    this.name = "ProvisionError";
    this.permanent = permanent;
  }
}

/**
 * The tag a service gets when its row names none (the api always stores one for new services). No
 * digest is written in source: each one is resolved on the first pull and recorded (data/images.ts).
 */
export const SERVICE_IMAGES: Record<ServiceKind, string> = {
  postgres: "postgres:17-alpine",
  redis: "redis:8.2-alpine",
  s3: "minio/minio:latest",
};

export const SERVICE_PORTS: Record<ServiceKind, number> = { postgres: 5432, redis: 6379, s3: 9000 };
const DATA_PATHS: Record<ServiceKind, string> = { postgres: "/var/lib/postgresql/data", redis: "/data", s3: "/data" };
export const dataPathFor = (kind: ServiceKind): string => DATA_PATHS[kind];

/** Files the managed deploy keeps in the service's volume, beside its data. */
export const SERVICE_FILES_DIR = ".dockify";
export const POSTGRES_PASSWORD_FILE = "postgres-password";
export const REDIS_CONFIG_FILE = "redis.conf";
/** The user the official image runs its server as, who must own the files above. */
export const SERVICE_USER: Record<ServiceKind, string> = { postgres: "postgres", redis: "redis", s3: "root" };

export interface ServiceApp {
  id: string;
  name: string;
  kind: ServiceKind;
  environmentId: string;
  projectId: string;
  image?: string | null;
  memoryLimitMb?: number | null;
  cpuLimit?: number | null;
  pidsLimit?: number | null;
}

export const LABEL_APP = "dockify.app";
export const LABEL_ENV = "dockify.environment";
export const LABEL_PROJECT = "dockify.project";
export const LABEL_ROLE = "dockify.role";

/** The same canonical name the deploy pipeline gives an app container (deploy/containers.ts). */
export const containerNameFor = (appId: string) => `dk-${appId}`;
export const volumeNameFor = (appId: string) => `dockify-data-${appId}`;
export const networkFor = (environmentId: string) => `dockify-env-${environmentId}`;
/** An internal network (no gateway) for one-off helpers and restore tests: reaches nothing. */
export const HELPER_NETWORK = "dockify-helpers";

/**
 * A service answers on its environment network under its app name, a name the tenant chose. Names
 * starting with dk- are Dockify's: its containers (dk-<appId>) and the per-deployment route aliases
 * the proxy dials (dk-route-<deploymentId>, edge module). A service under such an alias could
 * answer for a route target, so it never gets one, whatever an older row says. Permanent.
 */
export function assertServiceAlias(name: string): void {
  if (name.startsWith(RESERVED_NAME_PREFIX)) {
    throw new ProvisionError(`The service name ${name} starts with ${RESERVED_NAME_PREFIX}, which Dockify keeps for its own containers and routes; create the service again under another name`, true);
  }
}

/** Fresh credentials, the same shape the api seals (@dockify/db). */
export const generateCredentials = (kind: ServiceKind, appName: string): ServiceCredentials => generateServiceCredentials(kind, appName);

/**
 * Reads sealed credentials, either shape (see @dockify/db). `svc` only completes an older
 * install's bare password; the password itself never depends on it.
 */
export function parseCredentials(raw: string, svc: { kind: ServiceKind; name: string } = { kind: "redis", name: "the service" }): ServiceCredentials {
  return parseServiceCredentials(raw, svc).credentials;
}

/** What the connection endpoint and env auto-wiring hand to apps. Host is the in-network alias. */
export function connectionUrl(kind: ServiceKind, host: string, c: ServiceCredentials): string {
  const u = encodeURIComponent(c.user);
  const p = encodeURIComponent(c.password);
  const port = SERVICE_PORTS[kind];
  if (kind === "postgres") return `postgresql://${u}:${p}@${host}:${port}/${encodeURIComponent(c.database ?? "postgres")}`;
  if (kind === "redis") return `redis://${u}:${p}@${host}:${port}`;
  return `http://${host}:${port}`;
}

/**
 * The whole Redis config, written into the volume on every deploy. Snapshots, not the append-only
 * file: a restore swaps dump.rdb in, and Redis would ignore it while an AOF exists.
 */
export function redisConfig(c: ServiceCredentials): string {
  return [
    "# Written by Dockify on every deploy of this service. Changes here are replaced by the next deploy.",
    `port ${SERVICE_PORTS.redis}`,
    `dir ${DATA_PATHS.redis}`,
    `requirepass ${c.password}`,
    "appendonly no",
    "save 900 1 300 10 60 10000",
    "protected-mode yes",
    "",
  ].join("\n");
}

export interface ServiceOverrides {
  name?: string;
  /** The data volume. null runs without one, for a read of the service's shape only. */
  volume?: string | null;
  /** A throwaway Postgres: its password goes in the environment, with no file in its volume to read it from. */
  passwordInEnv?: boolean;
  role?: string;
  network?: string;
  /** The resolved image to run (an image id or a digest reference, data/images.ts). */
  image?: string;
  /** Postgres: PGDATA. Defaults to <volume>/pgdata; a volume adopted from an older container keeps its data at the root. */
  pgdata?: string;
}

/**
 * The container input for a service. Pure, so the tests can assert every invariant on it. The
 * deploy and restore paths always pass a resolved `image`; the fallback only names the kind's tag
 * for callers that read the labels.
 */
export function serviceInput(app: ServiceApp, creds: ServiceCredentials, over: ServiceOverrides = {}): ContainerInput {
  const kind = app.kind;
  const labels: Record<string, string> = {
    [LABEL_APP]: app.id,
    [LABEL_ENV]: app.environmentId,
    [LABEL_PROJECT]: app.projectId,
    [LABEL_ROLE]: over.role ?? `service-${kind}`,
  };
  const volume = over.volume === undefined ? volumeNameFor(app.id) : over.volume;
  const path = DATA_PATHS[kind];
  const files = `${path}/${SERVICE_FILES_DIR}`;
  // A one-off under its own name (the restore test) takes no alias; the service answers as its app name.
  if (!over.name) assertServiceAlias(app.name);
  const common = {
    name: over.name ?? containerNameFor(app.id),
    image: over.image ?? app.image ?? SERVICE_IMAGES[kind],
    network: over.network ?? networkFor(app.environmentId),
    aliases: over.name ? [] : [app.name],
    port: SERVICE_PORTS[kind],
    memoryMb: app.memoryLimitMb ?? (kind === "redis" ? 256 : 512),
    cpuCores: app.cpuLimit ?? null,
    pidsLimit: app.pidsLimit ?? null,
    volumes: volume ? [{ name: volume, mountPath: path }] : [],
    labels,
    restart: "unless-stopped" as const,
  };
  if (kind === "postgres") {
    const secret: Record<string, string> = volume && !over.passwordInEnv ? { POSTGRES_PASSWORD_FILE: `${files}/${POSTGRES_PASSWORD_FILE}` } : { POSTGRES_PASSWORD: creds.password };
    return {
      ...common,
      env: { POSTGRES_USER: creds.user, POSTGRES_DB: creds.database ?? "postgres", PGDATA: over.pgdata ?? `${path}/pgdata`, ...secret },
      healthcheck: { test: ["CMD-SHELL", 'pg_isready -q -h 127.0.0.1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"'], intervalSeconds: 5, timeoutSeconds: 5, retries: 12, startSeconds: 10 },
    };
  }
  if (kind === "redis") {
    if (!volume) throw new ProvisionError("Redis always runs on its own volume", true);
    return {
      ...common,
      // Started as its own user: the image's privilege drop (setpriv clearing the bounding set)
      // needs a capability Dockify never grants, and nothing here needs root.
      user: SERVICE_USER.redis,
      cmd: ["redis-server", `${files}/${REDIS_CONFIG_FILE}`],
      // Healthy only while Redis answers and refuses a client without the password.
      healthcheck: { test: ["CMD-SHELL", "redis-cli ping 2>&1 | grep -q NOAUTH"], intervalSeconds: 5, timeoutSeconds: 3, retries: 12, startSeconds: 5 },
    };
  }
  // Storage: never run (STORAGE_UNAVAILABLE). Described only so a container an older install
  // created still reads as this service's by its labels.
  return { ...common, cmd: ["server", path] };
}

export function serviceSpec(app: ServiceApp, creds: ServiceCredentials, over?: ServiceOverrides, hostCores?: number | null): ContainerSpec {
  return containerSpec(serviceInput(app, creds, over), hostCores);
}

/** Waits for a healthcheck to pass, or for a service without one to stay running. */
export async function waitReady(docker: DockerPort, id: string, timeoutMs = 90_000, pollMs = 1_000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  let steadyRuns = 0;
  for (;;) {
    const s = await docker.inspect(id);
    if (!s) throw new ProvisionError("the service container disappeared while starting", true);
    if (s.health === "healthy") return;
    if (s.health === "unhealthy") throw new ProvisionError("the service failed its health check", true);
    if (s.health === "none") {
      if (!s.running) throw new ProvisionError("the service exited while starting", true);
      if (++steadyRuns >= 3) return;
    }
    if (Date.now() > deadline) throw new ProvisionError("the service did not become ready in time", true);
    await sleep(pollMs);
  }
}

/**
 * A throwaway service container (the restore-test Postgres) on the volume it is given, started and
 * waited for. Without a named volume the image's VOLUME would become an anonymous one that nothing
 * could find again. Idempotent on a retry: an existing container for this app is reused
 * rather than duplicated. Every service with data goes through the managed deploy (data/managed.ts).
 */
export async function provisionService(
  docker: DockerPort,
  app: ServiceApp,
  creds: ServiceCredentials,
  opts: { name: string; image: string; role?: string; network?: string; timeoutMs?: number; volume: string; volumeLabels?: Record<string, string> },
): Promise<string> {
  if (app.kind === "s3") throw new ProvisionError(STORAGE_UNAVAILABLE, true);
  const spec = serviceSpec(app, creds, { name: opts.name, image: opts.image, ...(opts.role ? { role: opts.role } : {}), ...(opts.network ? { network: opts.network } : {}), volume: opts.volume, passwordInEnv: true }, docker.cpuCores);
  assertSafeSpec(spec);
  await docker.ensureNetwork(opts.network ?? networkFor(app.environmentId), { [LABEL_ENV]: app.environmentId }, opts.network === HELPER_NETWORK ? { internal: true } : undefined);
  await docker.ensureVolume(opts.volume, { "dockify.managed": "true", ...opts.volumeLabels });
  const existing = await docker.inspect(opts.name);
  if (existing && existing.labels[LABEL_APP] !== app.id) throw new ProvisionError(`container ${opts.name} exists and is not this app's`, true);
  const id = existing?.id ?? (await docker.createContainer(opts.name, spec));
  if (!existing?.running) await docker.start(id);
  await waitReady(docker, id, opts.timeoutMs);
  return id;
}
